import type { Metadata } from "next";

export const SITE_URL = "https://www.n-muhammad.uz";
export const SITE_NAME = "Mukhammad Numonkhujaev";
// Generated by app/opengraph-image.tsx
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: SITE_NAME };

export const SITE_DESCRIPTION =
	"Mukhammad Numonkhujaev — software engineering student at Kookmin University (GKS scholar) building full-stack products with Next.js, NestJS and GraphQL.";

// Per-page metadata: canonical URL, og:url and twitter card all point at the page itself.
export function pageMetadata({
	title,
	description,
	path,
}: {
	title: string;
	description: string;
	path: string;
}): Metadata {
	return {
		title,
		description,
		alternates: { canonical: path },
		openGraph: {
			title,
			description,
			url: path,
			siteName: SITE_NAME,
			locale: "en_US",
			type: "website",
			images: [OG_IMAGE],
		},
		twitter: {
			card: "summary_large_image",
			title,
			description,
			images: [OG_IMAGE.url],
		},
	};
}
